function dividir(a, b) {
  try {
    if (b === 0) {
      throw new Error("Divisão por zero não é permitida");
    }
    const resultado = a / b;
    console.log(`Resultado: ${resultado}`);
    return resultado;
  } catch (erro) {
    console.error(`Erro capturado: ${erro.message}`);
    return null;
  } finally {
    console.log("Operação de divisão terminada.");
  }
}

dividir(10, 2);
// Resultado: 5
// Operação de divisão terminada.

dividir(10, 0);
// Erro capturado: Divisão por zero não é permitida
// Operação de divisão terminada.

function testarFinally() {
  try {
    console.log("A tentar...");
    return "valor do try";
  } finally {
    console.log("finally executa sempre, mesmo com return no try");
  }
}

console.log(testarFinally());
// A tentar...
// finally executa sempre, mesmo com return no try
// valor do try

function overrideFinally() {
  try {
    return "do try";
  } finally {
    return "do finally"; // substitui o valor anterior - evite isto
  }
}

console.log(overrideFinally()); // "do finally"

function suportaLocalStorage() {
  try {
    const chave = "__teste_storage__";
    localStorage.setItem(chave, "1");
    localStorage.removeItem(chave);
    return true;
  } catch {
    // não interessa saber porque falhou (quota excedida, modo privado, etc.)
    return false;
  }
}

console.log(suportaLocalStorage());

function processar() {
  try {
    throw new Error("Falha no processamento");
  } finally {
    console.log("A libertar recursos...");
  }
}

try {
  processar();
} catch (erro) {
  console.log("Apanhado no chamador:", erro.message);
}
// A libertar recursos...
// Apanhado no chamador: Falha no processamento

// NÃO funciona: o erro escapa ao try/catch
try {
  setTimeout(() => {
    throw new Error("Erro assíncrono não apanhado");
  }, 100);
} catch (erro) {
  console.log("Isto nunca é executado:", erro.message);
}
// O setTimeout dispara depois de o try já ter terminado; o erro
// aparece como "Uncaught Error" e o catch acima nunca corre.

function falharAssincrono() {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error("Falha na promise")), 100);
  });
}

try {
  falharAssincrono(); // chamada sem await!
} catch (erro) {
  console.log("Também nunca é executado:", erro.message);
}

// Forma correta: aguardar dentro de uma função async
async function correr() {
  try {
    await falharAssincrono();
  } catch (erro) {
    console.log("Agora sim é apanhado:", erro.message);
  }
}
correr();

// Evitar: try demasiado abrangente
try {
  const dados = obterDadosDoFormulario();
  const idade = Number(dados.idade);
  registarNoServidor(idade); // só esta linha pode realmente falhar (rede)
  atualizarInterface(idade);
} catch (erro) {
  console.error("Algo correu mal:", erro.message);
}

// Preferível: try focado só na operação que pode falhar
const dados = obterDadosDoFormulario();
const idade = Number(dados.idade);

try {
  registarNoServidor(idade);
} catch (erro) {
  console.error("Falha ao registar no servidor:", erro.message);
} finally {
  atualizarInterface(idade);
}

