function analisarJSON(texto) {
  try {
    const objeto = JSON.parse(texto);
    return objeto;
  } catch (erro) {
    console.error(`JSON inválido: ${erro.message}`);
    return null;
  } finally {
    console.log("Análise terminada.");
  }
}

console.log(analisarJSON('{"nome": "Ana"}')); // { nome: 'Ana' }
console.log(analisarJSON("{nome: sem aspas}")); // null

