function configurarModo(modoSeguro) {
  try {
    if (!modoSeguro) {
      throw new Error("Modo inseguro não permitido");
    }
    return "ativo";
  } catch (erro) {
    console.error(erro.message);
    return "modo por omissão";
  } finally {
    console.log("Configuração concluída.");
  }
}

console.log(configurarModo(true));
// Configuração concluída.
// ativo

console.log(configurarModo(false));
// Modo inseguro não permitido
// Configuração concluída.
// modo por omissão

exercises.statement:
O código seguinte tenta validar um utilizador de forma assíncrona, mas o erro lançado dentro da Promise nunca é apanhado pelo try/catch:

function validarUtilizador(idade) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (idade < 18) {
        reject(new Error("Utilizador menor de idade"));
      } else {
        resolve("Utilizador válido");
      }
    }, 50);
  });
}

try {
  validarUtilizador(15);
} catch (erro) {
  console.log("Erro apanhado:", erro.message);
}

Explique, num comentário, porque é que este catch nunca é executado, e reescreva o código para que o erro seja corretamente apanhado, usando async/await.

exercises.solution_code:
function validarUtilizador(idade) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (idade < 18) {
        reject(new Error("Utilizador menor de idade"));
      } else {
        resolve("Utilizador válido");
      }
    }, 50);
  });
}

// O try/catch original falha porque validarUtilizador(15) devolve uma
// Promise de imediato; o try termina a sua execução (sem qualquer erro
// síncrono) muito antes de o setTimeout disparar e chamar reject, que
// acontece numa tarefa separada, já fora do try/catch original.

async function executar() {
  try {
    const resultado = await validarUtilizador(15);
    console.log(resultado);
  } catch (erro) {
    console.log("Erro apanhado:", erro.message);
  } finally {
    console.log("Validação terminada.");
  }
}

executar();
